/**
 * One stop of a product tour: the element being explained and a callout beside it with a title, a sentence, the
 * position in the tour and the buttons. Axes: placement (below, above, end: the callout sits beside the target),
 * tone, density.
 */
import { type ReactNode } from "react";
import { Block } from "../primitives/block/block";
import { Button } from "../primitives/button/button";
import { Group } from "../primitives/group/group";
import { Stack } from "../primitives/stack/stack";
import { Text } from "../primitives/text/text";
import { SectionFrame } from "../components/section-frame";
import { cn } from "../utils";

export type TourCalloutProps = {
  id: string;
  title: string;
  text: string;
  target: string;
  position: string;
  skip: string;
  next: string;
  placement?: "below" | "above" | "end";
  tone?: "default" | "muted";
  density?: "default" | "compact";
};

export function TourCallout({
  id,
  title,
  text,
  target,
  position,
  skip,
  next,
  placement = "below",
  tone = "default",
  density = "default",
}: TourCalloutProps) {
  return (
    <SectionFrame id={id} title={title} tone={tone} density={density}>
      <Block
        tag="div"
        className={cn(
          "flex gap-4",
          (
            (placement as string) === "end" ? "flex-col items-start md:flex-row md:items-center"
            : (placement as string) === "above" ? "flex-col-reverse items-start"
            : "flex-col items-start"
          )
        )}
        data-testid="tour"
        data-placement={placement}
      >
        <Button
          variant="outline"
          size="default"
          type="button"
          className="inset-ring-foreground"
          data-testid="tour-target"
        >
          {target}
        </Button>
        <Stack
          gap="4"
          align="stretch"
          className={cn(
            "w-full max-w-sm",
            "rounded bg-card inset-ring inset-ring-border",
            "p-4",
            "shadow-md"
          )}
          role="group"
          aria-label={title}
          data-testid="tour-callout"
        >
          <Text size="xs" className="text-muted-foreground">
            {position}
          </Text>
          <Text size="base" weight="semibold">
            {title}
          </Text>
          <Text size="sm" className="text-muted-foreground">
            {text}
          </Text>
          <Group gap="2" justify="end">
            <Button variant="ghost" size="sm" type="button">
              {skip}
            </Button>
            <Button variant="default" size="sm" type="button">
              {next}
            </Button>
          </Group>
        </Stack>
      </Block>
    </SectionFrame>
  );
}
